function geometry(){const type=E.geometryType.value,key=type==='bbox'?'bounding_box':type;if(type==='bbox'){const sw=nums(E.swCoord.value.trim()),ne=nums(E.neCoord.value.trim());if(sw.length!==2)throw new Error('SW must contain exactly latitude, longitude.');if(ne.length!==2)throw new Error('NE must contain exactly latitude, longitude.');const swLat=sw[0],swLon=sw[1],neLat=ne[0],neLon=ne[1];coord(swLon,swLat);coord(neLon,neLat);if(swLat>=neLat)throw new Error('SW latitude must be south of NE latitude.');if(swLon>=neLon)throw new Error('SW longitude must be west of NE longitude.');const v=[swLon,swLat,neLon,neLat];return{type:type,key:key,values:v,value:v.join(',')}}const a=nums(E.geometryValue.value.trim());let v=a.slice();if(type==='circle'){if(a.length!==3)throw new Error('Circle needs longitude, latitude and radius in meters.');coord(a[0],a[1]);if(a[2]<=0)throw new Error('Circle radius must be positive.')}else if(type==='point'){if(a.length!==2)throw new Error('Point needs longitude and latitude.');coord(a[0],a[1])}else if(type==='line'){if(a.length<4||a.length%2)throw new Error('Line needs at least two longitude/latitude pairs.');for(let i=0;i<a.length;i+=2)coord(a[i],a[i+1])}else{if(a.length<6||a.length%2)throw new Error('Polygon needs at least three longitude/latitude pairs.');for(let i=0;i<a.length;i+=2)coord(a[i],a[i+1]);if(a[0]!==a[a.length-2]||a[1]!==a[a.length-1])v.push(a[0],a[1])}return{type:type,key:key,values:v,value:v.join(',')}}
