async function aq(path,p){const key=E.openAqKey.value.trim()||S.aq;if(!key)throw new Error('OpenAQ API key is required.');const u=new URLSearchParams();Object.entries(p||{}).forEach(kv=>{if(kv[1]!==undefined&&kv[1]!==null&&kv[1]!=='')u.set(kv[0],String(kv[1]))});const proxy=String(OPENAQ_PROXY_BASE||'').replace(/\/$/,'');const url=(proxy?proxy+'/api/openaq':OPENAQ)+path+'?'+u.toString();const headers=proxy?{'X-OpenAQ-Key':key}:{'X-API-Key':key};let r;try{r=await fetch(url,{headers:headers})}catch(e){if(!proxy&&e instanceof TypeError)throw new Error('OpenAQ blocked the browser request (CORS/network policy). A server-side OpenAQ proxy is required for the GitHub Pages build.');throw new Error('OpenAQ network request failed: '+(e&&e.message?e.message:String(e)))}if(!r.ok){const body=await r.text().catch(()=>r.statusText);throw new Error('OpenAQ '+r.status+': '+body)}return r.json()}
